import { File as NodeFile } from 'node:buffer'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { createPinia, setActivePinia } from 'pinia'
import legacyJson from './fixtures/legacy-v2.pd?raw'
import { parseProjectJson } from '@/ts/projectImport'
import { validatePhoneProject } from '@/ts/phoneProject'
import { useProjectStore } from '@/stores/project'
import { useCanvasStore } from '@/stores/canvas'
import { usePaletteStore } from '@/stores/palette'
import { useWorkspaceStore } from '@/stores/workspace'

// Fixture generated by buildProjectPayload() from 815b2ba:js/pd.js, the last
// commit retaining the legacy source before a0d6b79 removed it. The last actual
// change to that exporter was 419f88e; its v2 payload matches b90d6f2 and the old directory.
describe('legacy PD import and v4 round trips', () => {
  beforeEach(() => {
    setActivePinia(createPinia())
    vi.stubGlobal('File', NodeFile)
  })
  afterEach(() => vi.unstubAllGlobals())

  it('converts the actual legacy exporter payload, including all six color types', () => {
    const data = parseProjectJson(legacyJson)
    expect(data.version).toBe(4)
    expect(data.type).toBe('single')
    expect([data.cols, data.rows]).toEqual([6, 2])
    expect(data.colorCard.colors.map((entry: { type: string }) => entry.type)).toEqual([
      'solid',
      'transparent',
      'pearl',
      'glow',
      'thermo',
      'photo',
    ])
    expect(data.colorCard.colors[1].color1).toBe('#d0d4d8')
    expect(data.colorCard.colors[4].color2).toBe('#0000ff')
    expect(data.colorCard.colors[5].color2).toBe('#1e2832')
    expect(data.layers[0].grid).toEqual([
      ['#cf0053', '#d0d4d8', '#7850c8', '#f0fab4', '#ff0000', '#ffffff'],
      ['', '#cf0053', '', '#ff0000', '', '#ffffff'],
    ])
    expect(() => validatePhoneProject(legacyJson)).not.toThrow()
  })

  it('uses the embedded palette when its name already exists and exports only v4', async () => {
    const palette = usePaletteStore()
    palette.registerCard({
      name: '旧版测试色卡',
      author: 'builtin',
      colors: [{ id: 'A01', type: 'solid', color1: '#000000', color2: null }],
    })
    palette.setColor('A01')
    const canvas = useCanvasStore()
    canvas.createCanvasGroup('previous group', 2, 2, 8)
    const project = useProjectStore()
    await project.loadProjectJson(legacyJson)
    expect(canvas.canvasGroup).toBeNull()
    expect(canvas.getCell(0, 0)).toBe('#cf0053')
    expect(palette.activeCard?.colors).toHaveLength(6)
    expect(palette.recentColorIds).toEqual([])
    const saved = JSON.parse(project.createProjectJson())
    expect(saved.version).toBe(4)
    expect(saved.type).toBe('single')
    expect(saved).not.toHaveProperty('canvas')
    expect(saved).not.toHaveProperty('palette')
    expect(saved.recentColorIds).toEqual([])
    saved.recentColorIds = ['A01', 'H01']
    await project.loadProjectJson(JSON.stringify(saved))
    const reloaded = JSON.parse(project.createProjectJson())
    expect(reloaded.layers).toEqual(saved.layers)
    expect(reloaded.colorCard).toEqual(saved.colorCard)
    expect(palette.recentColorIds).toEqual([])
  })

  it('preserves every legacy boundary pixel through a 1024 x 1024 group and v4 reload', async () => {
    const legacy = JSON.parse(legacyJson)
    legacy.canvas.width = legacy.canvas.height = 1024
    legacy.grid = Array.from({ length: 1024 }, () => Array(1024).fill(null))
    for (const [x, y, code] of [
      [0, 0, 'A01'],
      [63, 63, 'H01'],
      [64, 64, 'P01'],
      [1023, 1023, 'L01'],
    ] as const)
      legacy.grid[y][x] = code
    expect(() => validatePhoneProject(JSON.stringify(legacy))).toThrow('1–64')
    const project = useProjectStore()
    const canvas = useCanvasStore()
    await project.loadProjectJson(JSON.stringify(legacy))
    expect(canvas.canvasGroup).toMatchObject({ groupCols: 16, groupRows: 16, subSize: 64 })
    const saved = JSON.parse(project.createProjectJson())
    expect(saved.canvases[0][0].layers[0].grid[63][63]).toBe('#ff0000')
    expect(saved.canvases[1][1].layers[0].grid[0][0]).toBe('#7850c8')
    expect(saved.canvases[15][15].layers[0].grid[63][63]).toBe('#ffffff')
    await project.loadProjectJson(JSON.stringify(saved))
    expect(canvas.canvasGroup?.groupRows).toBe(16)
    expect(JSON.parse(project.createProjectJson()).canvases).toEqual(saved.canvases)
  })

  it('pads only the edges of a rectangular legacy canvas instead of cropping pixels', () => {
    const legacy = JSON.parse(legacyJson)
    legacy.canvas = { width: 65, height: 2 }
    legacy.grid = [Array(65).fill('A01'), Array(65).fill(null)]
    const data = parseProjectJson(JSON.stringify(legacy))
    expect([data.groupCols, data.groupRows]).toEqual([2, 1])
    expect(data.canvases[0][1].layers[0].grid[0][0]).toBe('#cf0053')
    expect(data.canvases[0][1].layers[0].grid[0][1]).toBe('')
  })

  it('rejects missing colors or corrupt palettes before changing the current project', async () => {
    const project = useProjectStore()
    const canvas = useCanvasStore()
    canvas.setCell(0, 0, '#123456')
    const before = project.createProjectJson()
    const legacy = JSON.parse(legacyJson)
    legacy.grid[0][0] = 'MISSING'
    await expect(project.loadProjectJson(JSON.stringify(legacy))).rejects.toThrow('缺少色号')
    expect(JSON.parse(project.createProjectJson()).layers).toEqual(JSON.parse(before).layers)
    legacy.grid[0][0] = 'A01'
    legacy.palette.entries[0].color1 = 'rgb(999, 0, 0)'
    await expect(project.loadProjectJson(JSON.stringify(legacy))).rejects.toThrow('颜色无效')
    expect(canvas.getCell(0, 0)).toBe('#123456')
  })

  it('keeps the existing v4 layers, group state, drawing settings, and images on reload', async () => {
    const canvas = useCanvasStore()
    const project = useProjectStore()
    const workspace = useWorkspaceStore()
    canvas.createCanvasGroup('新版组', 2, 1, 16)
    canvas.switchToSubCanvas(0, 1)
    canvas.setCell(3, 4, '#123456')
    const second = canvas.addLayer('第二层')
    canvas.setCell(4, 5, '#abcdef')
    second.visible = false
    canvas.renderMode = 'photo'
    canvas.symmetry = 'vertical'
    canvas.pixelShape = 'circle'
    canvas.showColorIds = true
    canvas.setUnderlay({ src: 'data:image/png;base64,AAAA', name: '底图.png' })
    workspace.referenceImage = { src: 'data:image/png;base64,BBBB', name: '参考图.png' }
    const saved = JSON.parse(project.createProjectJson())
    await project.loadProjectJson(JSON.stringify(saved))
    const result = JSON.parse(project.createProjectJson())
    expect(result.canvases).toEqual(saved.canvases)
    expect(result.activeGroupCol).toBe(1)
    expect(result.openGroupTabs).toEqual(saved.openGroupTabs)
    expect(result.referenceImage).toEqual(saved.referenceImage)
  })
})
